__global__ void grouped_convert_panel_kernel(
    const float* __restrict__ panel,
    __half* __restrict__ converted,
    int panel_rows,
    int trailing_rows,
    long long panel_stride_0,
    long long panel_stride_1,
    long long converted_stride_0,
    long long converted_stride_1
) {
    __shared__ float tile[32][33];
    const int batch = static_cast<int>(blockIdx.z);
    const int source_col = static_cast<int>(blockIdx.x) * 32 + threadIdx.x;
    const int source_row = static_cast<int>(blockIdx.y) * 32 + threadIdx.y;
    for (int offset = 0; offset < 32; offset += 8) {
        if (source_row + offset < panel_rows
                && source_col < trailing_rows) {
            tile[threadIdx.y + offset][threadIdx.x] = panel[
                static_cast<long long>(batch) * panel_stride_0
                + static_cast<long long>(source_row + offset) * panel_stride_1
                + source_col
            ];
        }
    }
    __syncthreads();

    const int output_col = static_cast<int>(blockIdx.y) * 32 + threadIdx.x;
    const int output_row = static_cast<int>(blockIdx.x) * 32 + threadIdx.y;
    for (int offset = 0; offset < 32; offset += 8) {
        if (output_row + offset < trailing_rows
                && output_col < panel_rows) {
            converted[
                static_cast<long long>(batch) * converted_stride_0
                + static_cast<long long>(output_row + offset)
                    * converted_stride_1
                + output_col
            ] = __float2half_rn(tile[threadIdx.x][threadIdx.y + offset]);
        }
    }
}

void grouped_convert_panel_cuda(
        torch::Tensor panel, torch::Tensor converted) {
    TORCH_CHECK(panel.is_cuda() && converted.is_cuda(),
                "CUDA tensors required");
