                && panel.size(0) == converted.size(0)
                && panel.size(1) == converted.size(2)
                && panel.size(2) == converted.size(1)
                && panel.stride(2) == 1 && converted.stride(2) == 1,
                "transposed panel shapes required");
    const int panel_rows = static_cast<int>(panel.size(1));
    const int trailing_rows = static_cast<int>(panel.size(2));
    const dim3 threads(32, 8, 1);
    const dim3 blocks(
        (trailing_rows + 31) / 32,
        (panel_rows + 31) / 32,
