@cuda.jit(device=True, forceinline=True)
def _g2048_load_diagonal(source, sample_base, tile, shared, leading):
    tid = cuda.threadIdx.x
    origin = tile * _G2048_NB
    row = tid // _G2048_NB
    col = tid - row * _G2048_NB
    index = tid
    source_index = sample_base + (origin + row) * leading + origin + col
    global_row_stride = _G2048_ROW_STRIDE * leading
    for _ in range(_G2048_LOADS_PER_THREAD):
        if row <= col:
            shared[index] = source[source_index]
        row += _G2048_ROW_STRIDE
        index += _G2048_NT
        source_index += global_row_stride
    cuda.syncthreads()


